CREATE TABLE semio_kit_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL);
CREATE TABLE semio_kit_type (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_kit_document(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), native_id TEXT NOT NULL, name TEXT NOT NULL, category TEXT NOT NULL);
CREATE TABLE semio_kit_design (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_kit_document(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), native_id TEXT NOT NULL, name TEXT NOT NULL);
CREATE TABLE semio_kit_piece (id INTEGER PRIMARY KEY, design_id INTEGER NOT NULL REFERENCES semio_kit_design(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), native_id TEXT NOT NULL, type_id INTEGER NOT NULL REFERENCES semio_kit_type(id), translation_x REAL, translation_y REAL, translation_z REAL, rotation_x REAL, rotation_y REAL, rotation_z REAL, rotation_w REAL, scale_x REAL, scale_y REAL, scale_z REAL, translation_x_ieee754_bits INTEGER, translation_x_numeric_class TEXT, translation_y_ieee754_bits INTEGER, translation_y_numeric_class TEXT, translation_z_ieee754_bits INTEGER, translation_z_numeric_class TEXT, rotation_x_ieee754_bits INTEGER, rotation_x_numeric_class TEXT, rotation_y_ieee754_bits INTEGER, rotation_y_numeric_class TEXT, rotation_z_ieee754_bits INTEGER, rotation_z_numeric_class TEXT, rotation_w_ieee754_bits INTEGER, rotation_w_numeric_class TEXT, scale_x_ieee754_bits INTEGER, scale_x_numeric_class TEXT, scale_y_ieee754_bits INTEGER, scale_y_numeric_class TEXT, scale_z_ieee754_bits INTEGER, scale_z_numeric_class TEXT);
CREATE TABLE semio_kit_connection (id INTEGER PRIMARY KEY, design_id INTEGER NOT NULL REFERENCES semio_kit_design(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), native_id TEXT NOT NULL, connecting_piece_id INTEGER NOT NULL REFERENCES semio_kit_piece(id), connecting_port TEXT NOT NULL, connected_piece_id INTEGER NOT NULL REFERENCES semio_kit_piece(id), connected_port TEXT NOT NULL);
CREATE TABLE semio_kit_reference (id INTEGER PRIMARY KEY, artifact_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL);
CREATE TABLE semio_kit_object_child (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_kit_document(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), child_id TEXT NOT NULL, target_reference_id INTEGER NOT NULL REFERENCES semio_kit_reference(id));
CREATE TABLE semio_kit_model_child (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_kit_document(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), child_id TEXT NOT NULL, target_reference_id INTEGER NOT NULL REFERENCES semio_kit_reference(id));
CREATE TABLE semio_kit_value_child (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_kit_document(id), child_id TEXT NOT NULL, target_reference_id INTEGER NOT NULL REFERENCES semio_kit_reference(id));
CREATE TABLE semio_kit_representation (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_kit_document(id), ordinal INTEGER NOT NULL CHECK (ordinal >= 0), type_id INTEGER NOT NULL REFERENCES semio_kit_type(id), target_reference_id INTEGER NOT NULL REFERENCES semio_kit_reference(id), pin_kind TEXT NOT NULL CHECK (pin_kind IN ('head','checkpoint','snapshot')), checkpoint_id TEXT, blob_id INTEGER REFERENCES semio_kit_blob(id));
CREATE TABLE semio_kit_blob (id INTEGER PRIMARY KEY, hash TEXT NOT NULL, size TEXT NOT NULL, media_type TEXT NOT NULL);
